//! Per-app session and lifecycle coordination.
//!
//! Callers perform external startup and cleanup and report their outcomes here.
//! Each app has its own lock; no Docker operation is performed under that lock.
//! The coordinator does not persist state or discover pre-existing resources.
use std::{
    collections::HashMap,
    sync::Arc,
    time::{Duration, Instant},
};
use tokio::sync::{Mutex, Notify};

/// A generation or session token, generated by the server.
pub type Token = u128;

/// A launch either starts a new generation or joins an existing one.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Launch {
    pub generation: Token,
    pub session: Token,
    pub start: bool,
}

/// Public state returned to clients without exposing launch configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Status {
    Stopped { error: Option<String> },
    Starting { generation: Token },
    Ready { generation: Token },
    Stopping { generation: Token },
}

#[derive(Debug)]
enum State {
    Stopped {
        error: Option<String>,
    },
    Starting {
        generation: Token,
        sessions: HashMap<Token, Instant>,
    },
    Ready {
        generation: Token,
        sessions: HashMap<Token, Instant>,
    },
    Stopping {
        generation: Token,
    },
}

/// Immediate admission outcome; stopping must be awaited outside manager locks.
pub(crate) enum Attempt {
    Accepted(Launch),
    Stopping,
}

/// Instructions for the caller after startup or session expiry.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Action {
    None,
    Stop(Token),
}

/// Serializes transitions for a single registered app.
///
/// `idle_timeout` is measured using monotonic [`Instant`] values. The caller
/// periodically calls `expire` and starts cleanup when it returns `Stop`.
/// Callers must finish every started generation, including failed startup, and
/// report workflow completion. New workflows reset unfinished resources.
/// A dropped lifecycle operation does not perform cleanup.
#[derive(Clone)]
pub struct AppLifecycle {
    state: Arc<Mutex<State>>,
    changed: Arc<Notify>,
    idle_timeout: Duration,
}
impl AppLifecycle {
    /// Create a stopped coordinator. A zero timeout is rejected.
    pub fn new(idle_timeout: Duration) -> Self {
        assert!(!idle_timeout.is_zero());
        Self {
            state: Arc::new(Mutex::new(State::Stopped { error: None })),
            changed: Arc::new(Notify::new()),
            idle_timeout,
        }
    }
    #[cfg(test)]
    async fn launch(&self, now: Instant) -> Launch {
        let mut accepted_at = now;
        loop {
            match self.try_launch(accepted_at).await {
                Attempt::Accepted(launch) => return launch,
                Attempt::Stopping => {
                    self.wait_until_not_stopping().await;
                    accepted_at = Instant::now();
                }
            }
        }
    }

    pub(crate) async fn try_launch(&self, now: Instant) -> Attempt {
        let mut state = self.state.lock().await;
        match &mut *state {
            State::Stopped { .. } => {
                let generation = rand::random();
                let session = rand::random();
                *state = State::Starting {
                    generation,
                    sessions: HashMap::from([(session, now)]),
                };
                Attempt::Accepted(Launch {
                    generation,
                    session,
                    start: true,
                })
            }
            State::Starting {
                generation,
                sessions,
            }
            | State::Ready {
                generation,
                sessions,
            } => {
                let session = loop {
                    let candidate = rand::random();
                    if !sessions.contains_key(&candidate) {
                        break candidate;
                    }
                };
                sessions.insert(session, now);
                Attempt::Accepted(Launch {
                    generation: *generation,
                    session,
                    start: false,
                })
            }
            State::Stopping { .. } => Attempt::Stopping,
        }
    }

    pub(crate) async fn wait_until_not_stopping(&self) {
        loop {
            let notified = self.changed.notified();
            tokio::pin!(notified);
            notified.as_mut().enable();
            if !matches!(*self.state.lock().await, State::Stopping { .. }) {
                return;
            }
            notified.await;
        }
    }
    /// Renew an existing, unexpired session of the current generation. Expired
    /// sessions are removed and cannot be revived by a late heartbeat.
    pub async fn heartbeat(&self, generation: Token, session: Token, now: Instant) -> bool {
        let mut state = self.state.lock().await;
        let sessions = match &mut *state {
            State::Starting {
                generation: current,
                sessions,
            }
            | State::Ready {
                generation: current,
                sessions,
            } if *current == generation => sessions,
            _ => return false,
        };
        match sessions.get_mut(&session) {
            Some(last) if now.saturating_duration_since(*last) < self.idle_timeout => {
                *last = now;
                true
            }
            Some(_) => {
                sessions.remove(&session);
                false
            }
            None => false,
        }
    }
    /// Finish startup. An abandoned starting generation transitions directly to
    /// stopping; the caller must carry out the returned cleanup action.
    pub async fn started(&self, generation: Token, now: Instant) -> Action {
        let mut state = self.state.lock().await;
        let State::Starting {
            generation: current,
            sessions,
        } = &mut *state
        else {
            return Action::None;
        };
        if *current != generation {
            return Action::None;
        }
        sessions.retain(|_, last| now.saturating_duration_since(*last) < self.idle_timeout);
        if sessions.is_empty() {
            *state = State::Stopping { generation };
            Action::Stop(generation)
        } else {
            let sessions = std::mem::take(sessions);
            *state = State::Ready {
                generation,
                sessions,
            };
            Action::None
        }
    }
    /// Begin teardown after startup or runtime failure.
    /// The caller awaits workflow completion before reporting `completed`.
    pub async fn fail(&self, generation: Token) -> Action {
        let mut state = self.state.lock().await;
        if matches!(&*state, State::Starting { generation: g, .. } | State::Ready { generation: g, .. } if *g == generation)
        {
            *state = State::Stopping { generation };
            Action::Stop(generation)
        } else {
            Action::None
        }
    }
    /// Close all viewer sessions and request shutdown. Startup is allowed to
    /// finish before cleanup so resource creation and teardown cannot race.
    pub async fn request_stop(&self) -> Action {
        let mut state = self.state.lock().await;
        match &mut *state {
            State::Starting { sessions, .. } => {
                sessions.clear();
                Action::None
            }
            State::Ready { generation, .. } => {
                let generation = *generation;
                *state = State::Stopping { generation };
                Action::Stop(generation)
            }
            _ => Action::None,
        }
    }
    /// Drop expired sessions. A ready generation with no viewers enters stopping.
    /// Starting is allowed to finish before cleanup to avoid racing the starter.
    pub async fn expire(&self, now: Instant) -> Action {
        let mut state = self.state.lock().await;
        match &mut *state {
            State::Starting { sessions, .. } => {
                sessions.retain(|_, last| now.saturating_duration_since(*last) < self.idle_timeout);
                Action::None
            }
            State::Ready {
                generation,
                sessions,
            } => {
                sessions.retain(|_, last| now.saturating_duration_since(*last) < self.idle_timeout);
                if sessions.is_empty() {
                    let generation = *generation;
                    *state = State::Stopping { generation };
                    Action::Stop(generation)
                } else {
                    Action::None
                }
            }
            _ => Action::None,
        }
    }
    /// Finish a generation and retain its diagnostic. Stale completions do nothing.
    /// The next workflow resets unfinished resources before starting workloads.
    pub async fn completed(&self, generation: Token, error: Option<String>) -> bool {
        let mut state = self.state.lock().await;
        if !matches!(&*state, State::Stopping { generation: current } if *current == generation) {
            return false;
        }
        *state = State::Stopped { error };
        drop(state);
        self.changed.notify_waiters();
        true
    }
    /// Snapshot the current app status.
    pub async fn status(&self) -> Status {
        match &*self.state.lock().await {
            State::Stopped { error } => Status::Stopped {
                error: error.clone(),
            },
            State::Starting { generation, .. } => Status::Starting {
                generation: *generation,
            },
            State::Ready { generation, .. } => Status::Ready {
                generation: *generation,
            },
            State::Stopping { generation } => Status::Stopping {
                generation: *generation,
            },
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn concurrent_launches_share_startup_and_sessions_are_independent() {
        // Arrange
        let app = AppLifecycle::new(Duration::from_secs(120));
        let now = Instant::now();

        // Act
        let (first, second) = tokio::join!(app.launch(now), app.launch(now));

        // Assert
        assert_eq!(first.generation, second.generation);
        assert_ne!(first.session, second.session);
        assert_ne!(first.start, second.start);
        assert_eq!(app.started(first.generation, now).await, Action::None);

        // Act
        assert!(
            app.heartbeat(
                first.generation,
                second.session,
                now + Duration::from_secs(100)
            )
            .await
        );
        let result = app.expire(now + Duration::from_secs(121)).await;

        // Assert
        assert_eq!(result, Action::None);
        assert!(
            !app.heartbeat(
                first.generation,
                first.session,
                now + Duration::from_secs(121)
            )
            .await
        );
        assert_eq!(
            app.status().await,
            Status::Ready {
                generation: first.generation
            }
        );

        // Act
        let result = app.expire(now + Duration::from_secs(221)).await;

        // Assert
        assert_eq!(result, Action::Stop(first.generation));
        assert!(
            !app.heartbeat(
                first.generation,
                second.session,
                now + Duration::from_secs(221)
            )
            .await
        );
    }

    #[tokio::test]
    async fn reconnect_before_expiry_joins_generation_and_late_heartbeat_fails() {
        // Arrange
        let app = AppLifecycle::new(Duration::from_secs(10));
        let now = Instant::now();
        let first = app.launch(now).await;
        app.started(first.generation, now).await;

        // Act
        let reconnected = app.launch(now + Duration::from_secs(9)).await;
        let expired = app
            .heartbeat(
                first.generation,
                first.session,
                now + Duration::from_secs(10),
            )
            .await;
        let live = app
            .heartbeat(
                reconnected.generation,
                reconnected.session,
                now + Duration::from_secs(10),
            )
            .await;

        // Assert
        assert_eq!(reconnected.generation, first.generation);
        assert!(!reconnected.start);
        assert!(!expired);
        assert!(live);
        assert_eq!(
            app.expire(now + Duration::from_secs(10)).await,
            Action::None
        );
    }

    #[tokio::test]
    async fn launch_waits_for_workflow_completion_and_stale_completion_is_ignored() {
        // Arrange
        let app = AppLifecycle::new(Duration::from_secs(1));
        let now = Instant::now();
        let first = app.launch(now).await;
        app.started(first.generation, now).await;
        assert_eq!(
            app.expire(now + Duration::from_secs(1)).await,
            Action::Stop(first.generation)
        );

        // Act
        let waiting = tokio::spawn({
            let app = app.clone();
            async move { app.launch(Instant::now()).await }
        });
        tokio::task::yield_now().await;

        // Assert
        assert!(!waiting.is_finished());
        assert!(!app.completed(first.generation.wrapping_add(1), None).await);

        // Act
        assert!(app.completed(first.generation, None).await);
        let second = waiting.await.unwrap();

        // Assert
        assert!(second.start);
        assert_ne!(first.generation, second.generation);
        assert!(
            !app.heartbeat(first.generation, first.session, Instant::now())
                .await
        );
    }

    #[tokio::test]
    async fn unfinished_cleanup_preserves_diagnostic_and_allows_a_fresh_attempt() {
        // Arrange
        let app = AppLifecycle::new(Duration::from_secs(120));
        let first = app.launch(Instant::now()).await;
        assert_eq!(
            app.fail(first.generation).await,
            Action::Stop(first.generation)
        );
        // Act
        assert!(
            app.completed(first.generation, Some("cleanup unverified".into()))
                .await
        );
        // Assert
        assert_eq!(
            app.status().await,
            Status::Stopped {
                error: Some("cleanup unverified".into())
            }
        );
        // Act: a fresh attempt must reach the workflow's strict pre-run reset.
        let next = app.launch(Instant::now()).await;
        // Assert
        assert!(next.start);
        assert_ne!(next.generation, first.generation);
    }

    #[tokio::test]
    async fn startup_without_viewers_is_cleaned_and_failure_remains_visible() {
        // Arrange
        let app = AppLifecycle::new(Duration::from_secs(2));
        let now = Instant::now();
        let launch = app.launch(now).await;

        // Act
        assert_eq!(app.expire(now + Duration::from_secs(2)).await, Action::None);
        let action = app
            .started(launch.generation, now + Duration::from_secs(2))
            .await;

        // Assert
        assert_eq!(action, Action::Stop(launch.generation));

        // Act
        assert!(
            app.completed(launch.generation, Some("startup failed".into()))
                .await
        );

        // Assert
        assert_eq!(
            app.status().await,
            Status::Stopped {
                error: Some("startup failed".into())
            }
        );
    }
}
